// spec: .qa/e2e/specs/prayer-history.md
// seed: tests/seed.user1.spec.ts
import { test, expect } from '@playwright/test';
import * as path from 'path';
import { suppressMilestoneWindow } from '../_helpers/milestone';

test.use({ storageState: path.resolve(__dirname, '../../../auth/user1.json') });

test.describe('История молитв', () => {
  test('PH-01 /journey/history: группировка по дням, HH:mm, поиск, подгрузка #6a86f800 @prod-safe', async ({ page }) => {
    await suppressMilestoneWindow(page); // окно уровня «עלית דרגה» не должно перекрывать экран
    // Эталон «סה״כ תפילות» на /home.
    await page.goto('/home');
    const totalRegion = page.getByRole('region', { name: /^סה״כ תפילות: \d+$/ });
    await expect(totalRegion).toBeVisible({ timeout: 20_000 });
    const total = Number(((await totalRegion.getAttribute('aria-label')) ?? '').match(/\d+/)![0]);

    // 1. Открыть `/journey/history`.
    await page.goto('/journey/history');
    // Имя S-26 «היסטוריית התפילות שלי» (#9e970625 / #56d002bd, עבר QA 21.10/25.10); старое «היסטוריית תפילות שלי» — регресс.
    await expect(page.getByText('היסטוריית התפילות שלי', { exact: true })).toBeVisible({ timeout: 20_000 });
    await expect(page.getByText('היסטוריית תפילות שלי', { exact: true })).toHaveCount(0);
    const search = page.getByRole('textbox', { name: 'חיפוש' });
    const rows = page.getByRole('region', { name: /, \d{2}:\d{2}(:\d{2})?$/ });
    const groups = page.getByRole('heading', { level: 1 });
    await expect(rows.first()).toBeVisible();
    // Группы «<евр. дата> · <греч. дата>», в строке — молитва и время.
    await expect(groups.first()).toHaveText(/^[א-ת״׳' ]+ · \d{1,2} [א-ת]+׳?$/);
    await expect(rows.first()).toHaveAccessibleName(/^[א-ת ()]+, .+ · .+, \d{2}:\d{2}(:\d{2})?$/);
    await expect(rows).toHaveCount(100);
    const hint = page.getByText('חיפוש בתפילות שנטענו בלבד — יש תפילות קודמות שטרם נטענו');

    // 2. По очереди ввести в поиск запросы; после каждого прочитать группы; очистить поиск.
    await search.fill('ערבית');
    await expect(rows).toHaveCount(1);
    await expect(rows.first()).toHaveAccessibleName(/^ערבית, /);
    await expect(hint).toBeVisible();

    await search.fill('23 בספט');
    await expect(groups).toHaveCount(1);
    await expect(groups.first()).toContainText('23 בספט');

    await search.fill('תשרי');
    await expect(rows).toHaveCount(100);

    await search.fill('י״ב');
    await expect(groups).toHaveCount(1);
    await expect(groups.first()).toContainText('י״ב תשרי');

    await search.fill('יב');
    await expect(groups).toHaveCount(1);
    await expect(groups.first()).toContainText('י״ב תשרי');

    await search.fill('zzzqq');
    await expect(page.getByText('לא נמצאו תפילות שמתאימות ל״zzzqq״.')).toBeVisible();
    await expect(rows).toHaveCount(0);

    await search.fill('');
    await expect(rows).toHaveCount(100);

    // 3. Нажать «טען תפילות קודמות» — загружаются все записи, кнопка исчезает.
    await page.getByRole('button', { name: 'טען תפילות קודמות' }).click();
    await expect(rows).toHaveCount(total);
    await expect(page.getByRole('button', { name: 'טען תפילות קודמות' })).toHaveCount(0);
  });
});
